-- GEBPSOICS Inventory Management System
-- Gov. Efren B. Pascual Sr. Orani Integrated Central School
--
-- MySQL 5.7+ / 8.x or MariaDB 10.3+  (InnoDB, utf8mb4).
-- Import this file first, then 02_seed.sql. In phpMyAdmin: choose your database -> Import.
-- No triggers, stored functions or special privileges are needed, so it works on shared hosting.
-- Property numbers, barcodes and issuance references are generated by the API (see Libraries/Db.php).
-- All DATETIME columns hold UTC; DATE columns are plain school-calendar dates.
-- Text comparisons are case-insensitive (utf8mb4_unicode_ci), so usernames, emails and property
-- numbers are unique regardless of capital letters.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------------------------------------------------------------------------
-- counters for property numbers, issuance references and barcodes
-- ---------------------------------------------------------------------------
CREATE TABLE doc_counters (
  prefix      VARCHAR(60)  NOT NULL,
  last_number INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (prefix)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- reference data
-- ---------------------------------------------------------------------------
CREATE TABLE departments (
  id         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  code       VARCHAR(30)  NOT NULL,
  name       VARCHAR(160) NOT NULL,
  head       VARCHAR(160) NOT NULL DEFAULT '',
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY departments_code_uq (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE rooms (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name          VARCHAR(120) NOT NULL,
  type          ENUM('Classroom','Laboratory','Storage Room','Office','Library','Gymnasium','Other') NOT NULL DEFAULT 'Classroom',
  department_id BIGINT UNSIGNED NOT NULL,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY rooms_dept_name_uq (department_id, name),
  CONSTRAINT rooms_department_fk FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE categories (
  id   BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  code VARCHAR(20)  NOT NULL,
  name VARCHAR(120) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY categories_code_uq (code),
  UNIQUE KEY categories_name_uq (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE personnel (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  emp_no        VARCHAR(30)  NOT NULL,
  name          VARCHAR(120) NOT NULL,
  designation   VARCHAR(120) NOT NULL DEFAULT '',
  department_id BIGINT UNSIGNED NULL,
  contact       VARCHAR(30)  NOT NULL DEFAULT '',
  email         VARCHAR(160) NOT NULL DEFAULT '',
  status        ENUM('Active','Inactive') NOT NULL DEFAULT 'Active',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY personnel_emp_no_uq (emp_no),
  KEY personnel_department_idx (department_id),
  CONSTRAINT personnel_department_fk FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- accounts
-- ---------------------------------------------------------------------------
CREATE TABLE users (
  id                   BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  username             VARCHAR(60)  NOT NULL,
  email                VARCHAR(160) NOT NULL,
  name                 VARCHAR(120) NOT NULL,
  password_hash        VARCHAR(255) NOT NULL,
  role                 ENUM('superadmin','admin','custodian','maintenance','staff') NOT NULL DEFAULT 'staff',
  status               ENUM('pending','active','inactive') NOT NULL DEFAULT 'pending',
  position             VARCHAR(120) NOT NULL DEFAULT '',
  department_id        BIGINT UNSIGNED NULL,
  personnel_id         BIGINT UNSIGNED NULL,
  phone                VARCHAR(30)  NOT NULL DEFAULT '',
  sms_opt_in           TINYINT(1)   NOT NULL DEFAULT 1,
  must_change_password TINYINT(1)   NOT NULL DEFAULT 0,
  last_login_at        DATETIME NULL,
  created_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at           DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY users_username_uq (username),
  UNIQUE KEY users_email_uq (email),
  KEY users_status_idx (status),
  CONSTRAINT users_department_fk FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL,
  CONSTRAINT users_personnel_fk  FOREIGN KEY (personnel_id)  REFERENCES personnel(id)   ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE password_resets (
  id         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id    BIGINT UNSIGNED NOT NULL,
  token_hash VARCHAR(100) NOT NULL,
  expires_at DATETIME NOT NULL,
  used_at    DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY password_resets_token_uq (token_hash),
  CONSTRAINT password_resets_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- equipment
-- ---------------------------------------------------------------------------
CREATE TABLE equipment (
  id               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  property_no      VARCHAR(40)  NOT NULL,
  barcode          VARCHAR(20)  NOT NULL,
  name             VARCHAR(160) NOT NULL,
  description      VARCHAR(1000) NOT NULL DEFAULT '',
  specs            VARCHAR(1000) NOT NULL DEFAULT '',
  brand            VARCHAR(80)  NOT NULL DEFAULT '',
  model            VARCHAR(80)  NOT NULL DEFAULT '',
  serial_no        VARCHAR(80)  NOT NULL DEFAULT '',
  acquisition_date DATE NOT NULL,
  cost             DECIMAL(14,2) NOT NULL DEFAULT 0,
  funding_source   VARCHAR(120) NOT NULL DEFAULT '',
  category_id      BIGINT UNSIGNED NOT NULL,
  `condition`      ENUM('New','Good','Fair','Poor') NOT NULL DEFAULT 'Good',
  status           ENUM('Available','Deployed','Under Repair','Defective','Condemned') NOT NULL DEFAULT 'Available',
  photo_path       VARCHAR(255) NULL,
  room_id          BIGINT UNSIGNED NOT NULL,
  department_id    BIGINT UNSIGNED NULL,
  assigned_to      BIGINT UNSIGNED NULL,
  created_by       BIGINT UNSIGNED NULL,
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY equipment_property_no_uq (property_no),
  UNIQUE KEY equipment_barcode_uq (barcode),
  KEY equipment_status_idx (status),
  KEY equipment_room_idx (room_id),
  KEY equipment_department_idx (department_id),
  KEY equipment_category_idx (category_id),
  KEY equipment_assigned_idx (assigned_to),
  KEY equipment_serial_idx (serial_no),
  CONSTRAINT equipment_category_fk   FOREIGN KEY (category_id)   REFERENCES categories(id)  ON DELETE RESTRICT,
  CONSTRAINT equipment_room_fk       FOREIGN KEY (room_id)       REFERENCES rooms(id)       ON DELETE RESTRICT,
  CONSTRAINT equipment_department_fk FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE RESTRICT,
  CONSTRAINT equipment_assigned_fk   FOREIGN KEY (assigned_to)   REFERENCES personnel(id)   ON DELETE SET NULL,
  CONSTRAINT equipment_created_fk    FOREIGN KEY (created_by)    REFERENCES users(id)       ON DELETE SET NULL,
  CONSTRAINT equipment_cost_ck CHECK (cost >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE supplies (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name          VARCHAR(160) NOT NULL,
  unit          VARCHAR(30)  NOT NULL DEFAULT 'pc',
  qty           INT NOT NULL DEFAULT 0,
  reorder_level INT NOT NULL DEFAULT 5,
  room_id       BIGINT UNSIGNED NULL,
  updated_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT supplies_room_fk FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE SET NULL,
  CONSTRAINT supplies_qty_ck CHECK (qty >= 0 AND reorder_level >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- issuance, transfers, maintenance, requests
-- ---------------------------------------------------------------------------
CREATE TABLE issuances (
  id               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  ref_no           VARCHAR(30) NOT NULL,
  equipment_id     BIGINT UNSIGNED NOT NULL,
  personnel_id     BIGINT UNSIGNED NOT NULL,
  type             ENUM('Assignment','Borrow') NOT NULL DEFAULT 'Assignment',
  issued_date      DATE NOT NULL,
  due_date         DATE NULL,
  returned_date    DATE NULL,
  received_by      VARCHAR(120)  NOT NULL DEFAULT '',
  purpose          VARCHAR(500)  NOT NULL DEFAULT '',
  remarks          VARCHAR(1000) NOT NULL DEFAULT '',
  status           ENUM('Active','Returned') NOT NULL DEFAULT 'Active',
  return_condition ENUM('Good','Fair','Poor') NULL,
  issued_by        BIGINT UNSIGNED NULL,
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY issuances_ref_no_uq (ref_no),
  KEY issuances_equipment_idx (equipment_id, status),
  KEY issuances_person_idx (personnel_id),
  KEY issuances_status_idx (status, type, due_date),
  CONSTRAINT issuances_equipment_fk FOREIGN KEY (equipment_id) REFERENCES equipment(id) ON DELETE CASCADE,
  CONSTRAINT issuances_personnel_fk FOREIGN KEY (personnel_id) REFERENCES personnel(id) ON DELETE RESTRICT,
  CONSTRAINT issuances_issued_by_fk FOREIGN KEY (issued_by)    REFERENCES users(id)     ON DELETE SET NULL,
  CONSTRAINT issuances_borrow_due_ck CHECK (type = 'Assignment' OR due_date IS NOT NULL),
  CONSTRAINT issuances_due_ck CHECK (due_date IS NULL OR due_date >= issued_date),
  CONSTRAINT issuances_returned_ck CHECK (returned_date IS NULL OR returned_date >= issued_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE transfers (
  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  equipment_id   BIGINT UNSIGNED NOT NULL,
  from_room_id   BIGINT UNSIGNED NULL,
  to_room_id     BIGINT UNSIGNED NOT NULL,
  transfer_date  DATE NOT NULL,
  reason         VARCHAR(1000) NOT NULL DEFAULT '',
  transferred_by BIGINT UNSIGNED NULL,
  created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY transfers_equipment_idx (equipment_id),
  CONSTRAINT transfers_equipment_fk FOREIGN KEY (equipment_id)   REFERENCES equipment(id) ON DELETE CASCADE,
  CONSTRAINT transfers_from_fk      FOREIGN KEY (from_room_id)   REFERENCES rooms(id)     ON DELETE SET NULL,
  CONSTRAINT transfers_to_fk        FOREIGN KEY (to_room_id)     REFERENCES rooms(id)     ON DELETE RESTRICT,
  CONSTRAINT transfers_by_fk        FOREIGN KEY (transferred_by) REFERENCES users(id)     ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE maintenance (
  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  equipment_id   BIGINT UNSIGNED NOT NULL,
  type           ENUM('Corrective','Preventive') NOT NULL,
  problem        VARCHAR(1000) NOT NULL,
  priority       ENUM('Normal','High') NOT NULL DEFAULT 'Normal',
  status         ENUM('Requested','Scheduled','In Progress','Completed','Cancelled') NOT NULL DEFAULT 'Requested',
  reported_by    BIGINT UNSIGNED NULL,
  reported_date  DATE NOT NULL,
  scheduled_date DATE NULL,
  assigned_to    BIGINT UNSIGNED NULL,
  completed_date DATE NULL,
  outcome        ENUM('Serviceable','Unserviceable') NULL,
  cost           DECIMAL(14,2) NOT NULL DEFAULT 0,
  repeat_months  INT NOT NULL DEFAULT 0,
  remarks        VARCHAR(1000) NOT NULL DEFAULT '',
  created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY maintenance_equipment_idx (equipment_id),
  KEY maintenance_status_idx (status, scheduled_date),
  CONSTRAINT maintenance_equipment_fk FOREIGN KEY (equipment_id) REFERENCES equipment(id) ON DELETE CASCADE,
  CONSTRAINT maintenance_reported_fk  FOREIGN KEY (reported_by)  REFERENCES users(id)     ON DELETE SET NULL,
  CONSTRAINT maintenance_assigned_fk  FOREIGN KEY (assigned_to)  REFERENCES users(id)     ON DELETE SET NULL,
  CONSTRAINT maintenance_cost_ck CHECK (cost >= 0),
  CONSTRAINT maintenance_repeat_ck CHECK (repeat_months BETWEEN 0 AND 60)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE equipment_requests (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  item          VARCHAR(160) NOT NULL,
  qty           INT NOT NULL DEFAULT 1,
  department_id BIGINT UNSIGNED NULL,
  reason        VARCHAR(2000) NOT NULL,
  needed_by     DATE NULL,
  requested_by  BIGINT UNSIGNED NOT NULL,
  status        ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',
  decided_by    BIGINT UNSIGNED NULL,
  decided_at    DATETIME NULL,
  remarks       VARCHAR(1000) NOT NULL DEFAULT '',
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY equipment_requests_status_idx (status),
  KEY equipment_requests_user_idx (requested_by),
  CONSTRAINT requests_department_fk FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL,
  CONSTRAINT requests_user_fk       FOREIGN KEY (requested_by)  REFERENCES users(id)       ON DELETE CASCADE,
  CONSTRAINT requests_decided_fk    FOREIGN KEY (decided_by)    REFERENCES users(id)       ON DELETE SET NULL,
  CONSTRAINT requests_qty_ck CHECK (qty > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE request_attachments (
  id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  request_id   BIGINT UNSIGNED NOT NULL,
  file_name    VARCHAR(150) NOT NULL,
  mime_type    VARCHAR(60)  NOT NULL,
  size_bytes   INT UNSIGNED NOT NULL,
  storage_path VARCHAR(255) NOT NULL,
  uploaded_by  BIGINT UNSIGNED NULL,
  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY request_attachments_request_idx (request_id),
  CONSTRAINT attachments_request_fk FOREIGN KEY (request_id)  REFERENCES equipment_requests(id) ON DELETE CASCADE,
  CONSTRAINT attachments_user_fk    FOREIGN KEY (uploaded_by) REFERENCES users(id)              ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- physical inventory (barcode / QR verification)
-- ---------------------------------------------------------------------------
CREATE TABLE inventory_sessions (
  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  room_id        BIGINT UNSIGNED NULL,
  scope_label    VARCHAR(160) NOT NULL DEFAULT 'Entire school',
  status         ENUM('In progress','Completed','Discarded') NOT NULL DEFAULT 'In progress',
  started_by     BIGINT UNSIGNED NULL,
  started_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  finished_at    DATETIME NULL,
  expected_count INT NULL,
  verified_count INT NULL,
  missing_count  INT NULL,
  PRIMARY KEY (id),
  KEY inventory_sessions_status_idx (status),
  CONSTRAINT sessions_room_fk FOREIGN KEY (room_id)    REFERENCES rooms(id) ON DELETE SET NULL,
  CONSTRAINT sessions_user_fk FOREIGN KEY (started_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE inventory_scans (
  id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  session_id   BIGINT UNSIGNED NOT NULL,
  equipment_id BIGINT UNSIGNED NULL,
  code         VARCHAR(120) NOT NULL,
  result       ENUM('verified','elsewhere','unknown') NOT NULL,
  scanned_by   BIGINT UNSIGNED NULL,
  scanned_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY inventory_scans_session_idx (session_id, result),
  KEY inventory_scans_equipment_idx (equipment_id),
  CONSTRAINT scans_session_fk   FOREIGN KEY (session_id)   REFERENCES inventory_sessions(id) ON DELETE CASCADE,
  CONSTRAINT scans_equipment_fk FOREIGN KEY (equipment_id) REFERENCES equipment(id)          ON DELETE CASCADE,
  CONSTRAINT scans_user_fk      FOREIGN KEY (scanned_by)   REFERENCES users(id)              ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- notifications, SMS, audit trail
-- ---------------------------------------------------------------------------
CREATE TABLE notification_reads (
  user_id   BIGINT UNSIGNED NOT NULL,
  alert_key VARCHAR(120) NOT NULL,
  read_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, alert_key),
  CONSTRAINT reads_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE sms_settings (
  id     TINYINT UNSIGNED NOT NULL DEFAULT 1,
  prefix VARCHAR(30) NOT NULL DEFAULT 'GEBPSOICS',
  types  VARCHAR(500) NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO sms_settings (id, prefix, types) VALUES
  (1, 'GEBPSOICS', '{"overdue":true,"maintenance":true,"request":true,"approval":true,"stock":true,"return":false}');

-- one row per message that staff marked as sent; dedupe_key keeps it out of the queue
CREATE TABLE sms_log (
  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  dedupe_key     VARCHAR(191) NOT NULL,
  recipient_name VARCHAR(120) NOT NULL,
  phone          VARCHAR(30)  NOT NULL,
  message        VARCHAR(1000) NOT NULL,
  type           VARCHAR(30)  NOT NULL,
  marked_by      BIGINT UNSIGNED NULL,
  created_at     DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY sms_log_dedupe_uq (dedupe_key),
  CONSTRAINT sms_log_user_fk FOREIGN KEY (marked_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE activity_log (
  id         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id    BIGINT UNSIGNED NULL,
  user_name  VARCHAR(120) NOT NULL DEFAULT 'System',
  kind       VARCHAR(30)  NOT NULL DEFAULT 'info',
  message    VARCHAR(1000) NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY activity_log_created_idx (created_at),
  CONSTRAINT activity_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------
-- convenience view for list screens
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW v_equipment AS
SELECT e.*,
       c.name AS category_name,
       c.code AS category_code,
       r.name AS room_name,
       d.name AS department_name,
       p.name AS assigned_name
FROM equipment e
JOIN categories c ON c.id = e.category_id
JOIN rooms r ON r.id = e.room_id
LEFT JOIN departments d ON d.id = e.department_id
LEFT JOIN personnel p ON p.id = e.assigned_to;

SET FOREIGN_KEY_CHECKS = 1;
